"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["2359"],{19609(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.publicacoes.ato_normativo.vinculo_tipo_de_entidade_invalido","status":422,"titulo":"O tipo da entidade vinculada est\xe1 vazio ou fora da forma can\xf4nica"},"descricao":{"codigo":"uniplus.publicacoes.ato_normativo.vinculo_tipo_de_entidade_invalido","requisitos":[],"oQueAconteceu":["O **tipo da entidade vinculada** ao ato est\xe1 vazio, ultrapassa 60 caracteres ou est\xe1 fora da forma can\xf4nica: come\xe7a por letra mai\xfascula e usa s\xf3 letras mai\xfasculas sem acento, algarismos e sublinhado entre palavras. O tipo \xe9 conferido exatamente como foi enviado, sem aparar espa\xe7os nem trocar a caixa.","O campo da recusa, em `errors[].field`, traz a posi\xe7\xe3o do v\xednculo, por exemplo `vinculos[0].entidadeTipo`.","Esta recusa \xe9 a do **registro** do ato (422). A consulta de atos por entidade tem a sua pr\xf3pria, com outro c\xf3digo, porque o tipo chega pela rota (400).","O registro do ato confere todos os campos do pedido numa s\xf3 passada: se mais de um campo estiver errado, a resposta traz uma recusa para cada um, na ordem do corpo do pedido, em `errors`. Corrija todos e reenvie."],"comoResolver":["Corrija o tipo da entidade no v\xednculo indicado, na forma can\xf4nica, e reenvie o pedido."],"ondeAparece":["Registro de ato normativo, quando o pedido traz v\xednculos"]},"modulo":{"id":"publicacoes","nome":"Publica\xe7\xf5es","assunto":"Ato normativo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);